**Премиум-скин внутри Telegram Mini App нужно продавать за Telegram Stars (`XTR`). Принимать за него 2 TON правила Telegram не разрешают:** это цифровой товар. [Официальное правило](https://core.telegram.org/bots/payments-stars#q-can-i-accept-payment-in-cryptocurrency-instead-of-telegram-stars).

Ниже пример со **100 Stars** — это условная цена, не пересчёт 2 TON.

Фронтенд запрашивает счёт и открывает его через `openInvoice`. Результат callback используется только для интерфейса; наличие скина проверяется на сервере.

```html
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<button id="buy">Купить скин — 100 ⭐</button>
<p id="status"></p>

<script>
const tg = Telegram.WebApp;
const statusEl = document.querySelector("#status");
tg.ready();

async function api(path, method = "GET") {
  const response = await fetch(path, {
    method,
    headers: { "X-Telegram-Init-Data": tg.initData }
  });
  if (!response.ok) throw new Error(await response.text());
  return response.json();
}

async function refreshSkin() {
  // Webhook может прийти чуть позже callback.
  for (let i = 0; i < 20; i++) {
    const { owned } = await api("/api/skin");
    if (owned) {
      statusEl.textContent = "Скин доступен!";
      return;
    }
    await new Promise(resolve => setTimeout(resolve, 500));
  }
  statusEl.textContent = "Подтверждение ещё обрабатывается.";
}

document.querySelector("#buy").onclick = async () => {
  try {
    const { url } = await api("/api/invoice", "POST");
    tg.openInvoice(url, status => {
      if (status === "paid" || status === "pending") {
        refreshSkin().catch(error => {
          statusEl.textContent = error.message;
        });
      } else {
        statusEl.textContent = "Оплата не завершена.";
      }
    });
  } catch (error) {
    statusEl.textContent = error.message;
  }
};
</script>
```

Бэкенд: Node.js 20+, Express 5, `better-sqlite3`. Переменные окружения: `BOT_TOKEN`, `WEBHOOK_SECRET` — случайный секрет, `PUBLIC_URL` — публичный HTTPS-адрес сервера.

```js
import express from "express";
import Database from "better-sqlite3";
import { createHmac, timingSafeEqual, randomUUID } from "node:crypto";

const { BOT_TOKEN, WEBHOOK_SECRET, PUBLIC_URL } = process.env;
if (!BOT_TOKEN || !WEBHOOK_SECRET || !PUBLIC_URL) {
  throw new Error("Missing configuration");
}

const PRICE_XTR = 100; // Цену определяет сервер.
const app = express();
app.use(express.json({ limit: "32kb" }));

const db = new Database("payments.sqlite");
db.pragma("journal_mode = WAL");
db.exec(`
  CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY,
    uid TEXT NOT NULL,
    amount INTEGER NOT NULL,
    charge TEXT UNIQUE
  );
  CREATE TABLE IF NOT EXISTS skins (
    uid TEXT PRIMARY KEY
  );
  CREATE TABLE IF NOT EXISTS refunds (
    charge TEXT PRIMARY KEY,
    uid TEXT NOT NULL
  );
`);

const get = (sql, ...args) => db.prepare(sql).get(...args);
const run = (sql, ...args) => db.prepare(sql).run(...args);
const order = id => get("SELECT * FROM orders WHERE id = ?", id);
const owns = uid => !!get("SELECT 1 FROM skins WHERE uid = ?", uid);

async function bot(method, params) {
  const response = await fetch(
    `https://api.telegram.org/bot${BOT_TOKEN}/${method}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(params),
      signal: AbortSignal.timeout(4000)
    }
  );
  const data = await response.json();
  if (!response.ok || !data.ok) {
    throw new Error(data.description || "Telegram API error");
  }
  return data.result;
}

// Проверка initData по алгоритму Telegram.
function userId(raw) {
  const p = new URLSearchParams(raw);
  if (new Set(p.keys()).size !== [...p].length) {
    throw new Error("Duplicate fields");
  }

  const hash = p.get("hash");
  if (!/^[a-f0-9]{64}$/i.test(hash ?? "")) throw new Error("Bad hash");
  p.delete("hash");
  p.sort(); // При HMAC поле signature, если есть, сохраняем.

  const check = [...p].map(([k, v]) => `${k}=${v}`).join("\n");
  const secret = createHmac("sha256", "WebAppData")
    .update(BOT_TOKEN).digest();
  const expected = createHmac("sha256", secret).update(check).digest();

  if (!timingSafeEqual(expected, Buffer.from(hash, "hex"))) {
    throw new Error("Invalid initData");
  }

  const timestamp = Number(p.get("auth_date"));
  const now = Date.now() / 1000;
  // Один час — выбранный здесь срок действия авторизации.
  if (!Number.isInteger(timestamp) ||
      timestamp > now + 30 || now - timestamp > 3600) {
    throw new Error("Expired initData");
  }

  const user = JSON.parse(p.get("user") || "{}");
  if (!Number.isSafeInteger(user.id) || user.id <= 0) {
    throw new Error("Invalid user");
  }
  return String(user.id);
}

function auth(req, res, next) {
  try {
    req.uid = userId(req.get("X-Telegram-Init-Data") || "");
    next();
  } catch {
    res.status(401).send("Откройте Mini App заново");
  }
}

app.get("/api/skin", auth, (req, res) => {
  res.json({ owned: owns(req.uid) });
});

app.post("/api/invoice", auth, async (req, res) => {
  if (owns(req.uid)) return res.status(409).send("Скин уже приобретён");

  const id = randomUUID();
  run("INSERT INTO orders(id, uid, amount) VALUES (?, ?, ?)",
      id, req.uid, PRICE_XTR);

  const url = await bot("createInvoiceLink", {
    title: "Премиум-скин",
    description: "Премиум-скин для игры",
    payload: id,
    currency: "XTR",
    provider_token: "",
    prices: [{ label: "Премиум-скин", amount: PRICE_XTR }]
  });
  res.json({ url });
});

function matches(o, uid, payment) {
  return !!o &&
    o.uid === String(uid) &&
    payment.currency === "XTR" &&
    payment.total_amount === o.amount;
}

// Оплата и право на скин фиксируются одной транзакцией.
const deliver = db.transaction((uid, payment) => {
  const o = order(payment.invoice_payload);
  if (!matches(o, uid, payment)) throw new Error("Payment mismatch");

  const charge = payment.telegram_payment_charge_id;

  // Повторная доставка того же уведомления.
  if (o.charge === charge ||
      get("SELECT 1 FROM refunds WHERE charge = ?", charge)) return;

  // Отдельный реальный платёж за уже купленный скин.
  if (o.charge || owns(o.uid)) {
    run("INSERT INTO refunds(charge, uid) VALUES (?, ?)", charge, o.uid);
    return;
  }

  run("UPDATE orders SET charge = ? WHERE id = ?", charge, o.id);
  run("INSERT INTO skins(uid) VALUES (?)", o.uid);
});

app.post("/telegram/webhook", async (req, res) => {
  if (req.get("X-Telegram-Bot-Api-Secret-Token") !== WEBHOOK_SECRET) {
    return res.sendStatus(403);
  }

  const q = req.body.pre_checkout_query;
  if (q) {
    const o = order(q.invoice_payload);
    const ok = matches(o, q.from.id, q) && !o.charge && !owns(o.uid);

    // Telegram должен получить ответ в течение 10 секунд.
    await bot("answerPreCheckoutQuery", {
      pre_checkout_query_id: q.id,
      ok,
      ...(ok ? {} : { error_message: "Заказ недоступен или уже оплачен" })
    });
  }

  const message = req.body.message;
  if (message?.successful_payment) {
    deliver(message.from.id, message.successful_payment);
  }

  // Ответ после COMMIT; при ошибке ниже вернём 500 для повтора.
  res.sendStatus(200);
});

app.use((error, req, res, next) => {
  console.error(error);
  res.status(500).send("Ошибка обработки");
});

app.listen(3000);

await bot("setWebhook", {
  url: `${PUBLIC_URL}/telegram/webhook`,
  secret_token: WEBHOOK_SECRET,
  allowed_updates: ["message", "pre_checkout_query"]
});
```

Сервер проверяет подпись [`initData`](https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app), владельца заказа, валюту и сохранённую сумму. **Скин выдаётся только после `successful_payment`**; разрешение `pre_checkout_query` само по себе оплату не подтверждает. Использование скина в игре также проверяйте через серверную таблицу `skins`.

Для запуска в продакшене добавьте обработчик очереди `refunds` через `refundStarPayment` и команду `/paysupport`. SQLite должен храниться на постоянном диске.
